/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(AVATCVTable, QuotationItemsDelete), FormControlEventType::Clicked)]
public static void QuotationItemsDelete_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormDataSource  QuotationItemsDS;
    QuotationItemsDS = sender.formRun().dataSource(formDataSourceStr(AVATCVTable, AVATCVQuotationItems));
    ttsbegin;
    if (QuotationItemsDS.anyMarked())
    {
        QuotationItemsDS.deleteMarked();
    }
    else if (getFirstSelection(QuotationItemsDS))
    {
        QuotationItemsDS.delete();
    }
    ttscommit;
    QuotationItemsDS.executeQuery();
}

